/**
 * Exo 3mm driver: mirrors PolyBench/C 3mm.c but calls the Exo-generated kernel.
 */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "3mm.h"

/* Include the Exo-generated kernel header. */
#include "generated/3mm/3mm.h"


/* Array initialization. */
static
void init_array(int ni, int nj, int nk, int nl, int nm,
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NM,nj,nm),
		DATA_TYPE POLYBENCH_2D(D,NM,NL,nm,nl))
{
  int i, j;

  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / (5*ni);
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) ((i*(j+1)+2) % nj) / (5*nj);
  for (i = 0; i < nj; i++)
    for (j = 0; j < nm; j++)
      C[i][j] = (DATA_TYPE) (i*(j+3) % nl) / (5*nl);
  for (i = 0; i < nm; i++)
    for (j = 0; j < nl; j++)
      D[i][j] = (DATA_TYPE) ((i*(j+2)+2) % nk) / (5*nk);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(G,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("G");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, G[i][j]);
    }
  POLYBENCH_DUMP_END("G");
  POLYBENCH_DUMP_FINISH;
}

/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *
from exo.API_cursors import ForCursor


@proc
def kernel_3mm_base(
    ni: size,
    nj: size,
    nk: size,
    nl: size,
    nm: size,
    E: DATA_TYPE[ni, nj] @ DRAM,
    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nk, nj] @ DRAM,
    F: DATA_TYPE[nj, nl] @ DRAM,
    C: DATA_TYPE[nj, nm] @ DRAM,
    D: DATA_TYPE[nm, nl] @ DRAM,
    G: DATA_TYPE[ni, nl] @ DRAM,
):
    # E := A * B
    for i in seq(0, ni):
        for j in seq(0, nj):
            E[i, j] = 0.0
            for k in seq(0, nk):
                E[i, j] += A[i, k] * B[k, j]

    # F := C * D
    for i in seq(0, nj):
        for j in seq(0, nl):
            F[i, j] = 0.0
            for k in seq(0, nm):
                F[i, j] += C[i, k] * D[k, j]

    # G := E * F
    for i in seq(0, ni):
        for j in seq(0, nl):
            G[i, j] = 0.0
            for k in seq(0, nj):
                G[i, j] += E[i, k] * F[k, j]


# Start from the mathematically clear base kernel.
kernel_3mm = kernel_3mm_base

# ---------------------------------------------------------------------------
# Schedule 1: improve memory locality by reordering the inner loops.
# We transform each GEMM so that its loop order becomes i-k-j:
#   - This keeps A/C/E accessed row-wise (good spatial locality).
#   - It changes B/D/F access from column-wise to row-wise, improving cache use.
# To safely reorder j and k, we first fission the j-loop body so that
# the zeroing (E/F/G[i,j] = 0) is in a separate loop from the reduction.
# ---------------------------------------------------------------------------

# --- Reorder loops in the E := A * B computation --------------------------------
# Split the j-loop in the E computation into:
#   for i:
#       for j: E[i,j] = 0
#       for j: for k: E[i,j] += ...
cE_init = kernel_3mm.find("E[_, _] = 0.0")
kernel_3mm = fission(kernel_3mm, cE_init.after())

# Forward the cursor into the transformed procedure.
cE_init_fwd = kernel_3mm.forward(cE_init)

# Walk up to the enclosing j-loop that performs initialization.
j_init_E = cE_init_fwd.parent()
while not isinstance(j_init_E, ForCursor):
    j_init_E = j_init_E.parent()

# The next statement in the same i-loop is the j-loop that contains the k-loop
# (the accumulation loop). Reorder that j-k pair into k-j.
j_accum_E = j_init_E.next()
kernel_3mm = reorder_loops(kernel_3mm, j_accum_E)

# After this, the E computation has the form:
#   for i in 0..ni:
#       for j in 0..nj:
#           E[i,j] = 0
#   for i in 0..ni:
#       for k in 0..nk:
#           for j in 0..nj:
#               E[i,j] += A[i,k] * B[k,j]


# --- Reorder loops in the F := C * D computation --------------------------------
cF_init = kernel_3mm.find("F[_, _] = 0.0")
kernel_3mm = fission(kernel_3mm, cF_init.after())
cF_init_fwd = kernel_3mm.forward(cF_init)

j_init_F = cF_init_fwd.parent()
while not isinstance(j_init_F, ForCursor):
    j_init_F = j_init_F.parent()

j_accum_F = j_init_F.next()
kernel_3mm = reorder_loops(kernel_3mm, j_accum_F)

# Final structure for F:
#   for i in 0..nj:
#       for j in 0..nl:
#           F[i,j] = 0
#   for i in 0..nj:
#       for k in 0..nm:
#           for j in 0..nl:
#               F[i,j] += C[i,k] * D[k,j]


# --- Reorder loops in the G := E * F computation --------------------------------
cG_init = kernel_3mm.find("G[_, _] = 0.0")
kernel_3mm = fission(kernel_3mm, cG_init.after())
cG_init_fwd = kernel_3mm.forward(cG_init)

j_init_G = cG_init_fwd.parent()
while not isinstance(j_init_G, ForCursor):
    j_init_G = j_init_G.parent()

j_accum_G = j_init_G.next()
kernel_3mm = reorder_loops(kernel_3mm, j_accum_G)

# Final structure for G:
#   for i in 0..ni:
#       for j in 0..nl:
#           G[i,j] = 0
#   for i in 0..ni:
#       for k in 0..nj:
#           for j in 0..nl:
#               G[i,j] += E[i,k] * F[k,j]


# ---------------------------------------------------------------------------
# Schedule 2: parallelize the outer i-loops.
# Each row i of E, F, and G is independent, so we can safely parallelize
# all loops that iterate over i. The Exo backend will lower this to
# OpenMP parallel-for pragmas, exploiting the 32-core machine.
# ---------------------------------------------------------------------------
for loop in kernel_3mm.find_all("for i in _:_"):
    kernel_3mm = parallelize_loop(kernel_3mm, loop)

# ---------------------------------------------------------------------------
# Finalize: rename the optimized procedure to the externally visible name
# expected by the C driver, i.e., kernel_3mm.
# ---------------------------------------------------------------------------
kernel_3mm = rename(kernel_3mm, "kernel_3mm")
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;
  int nm = NM;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(E, DATA_TYPE, NI, NJ, ni, nj);
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, NI, NK, ni, nk);
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, NK, NJ, nk, nj);
  POLYBENCH_2D_ARRAY_DECL(F, DATA_TYPE, NJ, NL, nj, nl);
  POLYBENCH_2D_ARRAY_DECL(C, DATA_TYPE, NJ, NM, nj, nm);
  POLYBENCH_2D_ARRAY_DECL(D, DATA_TYPE, NM, NL, nm, nl);
  POLYBENCH_2D_ARRAY_DECL(G, DATA_TYPE, NI, NL, ni, nl);

  /* Initialize array(s). */
  init_array (ni, nj, nk, nl, nm,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D views to 1D pointers. */
  kernel_3mm (/*ctxt=*/NULL, ni, nj, nk, nl, nm,
