    M: size,
    N: size,
    K: size,
    A: DATA_TYPE[M, K] @ DRAM,
    B: DATA_TYPE[K, N] @ DRAM,
    C: DATA_TYPE[M, N] @ DRAM,
):
    # Zero-initialize the output matrix.
    for i in seq(0, M):
        for j in seq(0, N):
            C[i, j] = 0.0

    # Accumulate C = A * B using i–k–j loop order.
    for i in seq(0, M):
        for k in seq(0, K):
            for j in seq(0, N):
